function f(name:string,label:string,type?:string,options?:string[]):Field{return{name,label,type,options}}
const pretty=(s:string)=>s.replace(/([A-Z])/g," $1").replace(/^./,x=>x.toUpperCase());
const shown=(v:unknown)=>v==null||v===""?"—":String(v).length>30?String(v).slice(0,29)+"…":String(v);
export function OperationalWorkspace({section,flash}:{section:string;flash:(s:string)=>void}){
 const c=views[section]||views["AI systems"],[data,setData]=useState<Record<string,unknown>>({}),[open,setOpen]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState("");
 const endpoint=c.endpoint||"/api/governance";
 const load=()=>fetch(endpoint).then(async r=>{const j=await r.json();if(!r.ok)throw new Error(j.error);setData(j);setError("")}).catch(e=>setError(e.message));
 useEffect(()=>{void load()},[section]);const rows=Array.isArray(data[c.key])?data[c.key] as Array<Record<string,unknown>>:[];
 async function transition(grantCode:string,transition:string){setBusy(true);try{const r=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"access_transition",grantCode,transition})});const j=await r.json();if(!r.ok)throw new Error(j.error);flash(`Access ${transition} completed`);await load()}catch(x){setError(x instanceof Error?x.message:"Request failed")}finally{setBusy(false)}}
 async function approveGate(gateCode:string){setBusy(true);try{const r=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"approve_deployment_gate",gateCode})});const j=await r.json();if(!r.ok)throw new Error(j.error);flash("Deployment gate approved");await load()}catch(x){setError(x instanceof Error?x.message:"Request failed")}finally{setBusy(false)}}
 async function agencyTransition(decisionCode:string,transition:string){setBusy(true);try{const r=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"agency_transition",decisionCode,transition})});const j=await r.json();if(!r.ok)throw new Error(j.error);flash(`Institutional decision ${transition} completed`);await load()}catch(x){setError(x instanceof Error?x.message:"Request failed")}finally{setBusy(false)}}
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);try{const payload=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:c.action,...payload})});const j=await r.json();if(!r.ok)throw new Error(j.error);setOpen(false);flash(`${c.button} completed`);await load()}catch(x){setError(x instanceof Error?x.message:"Request failed")}finally{setBusy(false)}}
 const actor=data.actor as {displayName?:string;role?:string;organizationName?:string}|undefined;
 return <div className="page ops-page"><div className="ops-hero"><div><p className="eyebrow">INSTITUTIONAL EXECUTION LAYER</p><h1>{c.title}</h1><p>{c.intro}</p></div>{c.action&&<button className="primary" onClick={()=>setOpen(true)}>＋ {c.button}</button>}</div><div className="ops-context"><span>Institution <b>{actor?.organizationName||"Loading…"}</b></span><span>User <b>{actor?.displayName||"Loading…"}</b></span><span>Role <b>{actor?.role||"—"}</b></span></div>{error&&<div className="ops-error">{error}</div>}<section className="panel ops-table"><div className="panel-head"><div><p className="eyebrow">LIVE GOVERNANCE RECORD</p><h2>{rows.length} record{rows.length===1?"":"s"}</h2></div><button onClick={load}>Refresh ↻</button></div><div className="table-wrap"><table><thead><tr>{c.columns.map(x=><th key={x}>{pretty(x)}</th>)}</tr></thead><tbody>{rows.length?rows.map((row,i)=><tr key={row.id||row.email||i}>{c.columns.map(x=><td key={x} title={String(row[x]||"")}>{x==="actions"&&c.key==="accessGrants"?<div className="row-actions">{row.status==="requested"&&<button disabled={busy} onClick={()=>transition(row.grantCode,"approve")}>Approve</button>}{row.status==="active"&&<button disabled={busy} onClick={()=>transition(row.grantCode,"review")}>Review</button>}{["requested","active"].includes(row.status)&&<button disabled={busy} onClick={()=>transition(row.grantCode,"revoke")}>Revoke</button>}</div>:x==="actions"&&c.key==="agencyAssessments"?<div className="row-actions">{row.outcome==="READY_FOR_APPROVAL"&&<button disabled={busy} onClick={()=>agencyTransition(row.decisionCode,"approve")}>Authorize adoption</button>}{row.outcome==="ADOPTION_AUTHORIZED"&&<><button disabled={busy} onClick={()=>agencyTransition(row.decisionCode,"suspend")}>Suspend</button><button disabled={busy} onClick={()=>agencyTransition(row.decisionCode,"discontinue")}>Discontinue</button></>}{row.outcome==="SUSPENDED"&&<button disabled={busy} onClick={()=>agencyTransition(row.decisionCode,"discontinue")}>Discontinue</button>}{["BLOCKED","REFUSED","DISCONTINUED"].includes(row.outcome)&&<span>{row.outcome.replaceAll("_"," ")}</span>}</div>:x==="actions"&&c.key==="deploymentGates"?<div className="row-actions">{row.outcome==="READY_FOR_APPROVAL"&&<button disabled={busy} onClick={()=>approveGate(row.gateCode)}>Approve deployment</button>}{row.outcome==="BLOCKED"&&<span>Resolve gaps</span>}{row.outcome==="APPROVED"&&<span>✓ Active</span>}</div>:x.includes("Hash")?<code>{shown(row[x])}</code>:shown(row[x])}</td>)}</tr>):<tr><td className="empty-row" colSpan={c.columns.length}>No records yet. {c.action?`Use “${c.button}” to create the first defensible record.`:"Events appear automatically as work is completed."}</td></tr>}</tbody></table></div></section><div className="ops-assurance"><b>Control principle</b><span>Rules before AI</span><span>Institution isolation</span><span>Named accountability</span><span>Immutable evidence</span><span>Human authorization</span></div>{open&&<div className="modal-backdrop" onMouseDown={()=>setOpen(false)}><form className="modal" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><p className="eyebrow">CONTROLLED WORKFLOW</p><h2>{c.button}</h2></div><button type="button" onClick={()=>setOpen(false)}>×</button></div>{c.fields?.map(x=><label key={x.name}>{x.label}{x.type==="select"?<select name={x.name} required>{x.options?.map(o=><option key={o}>{o}</option>)}</select>:x.type==="textarea"?<textarea name={x.name} required/>:<input name={x.name} type={x.type||"text"} required/>}</label>)}{error&&<div className="ops-error">{error}</div>}<div className="modal-actions"><button type="button" onClick={()=>setOpen(false)}>Cancel</button><button className="primary" disabled={busy}>{busy?"Recording…":c.button}</button></div></form></div>}</div>
}
